<script setup>
import {computed,reactive,ref} from 'vue';
import {ElMessage} from 'element-plus';
import ParentTutoring from './components/ParentTutoring.vue';
import HandwritingFeedback from './components/HandwritingFeedback.vue';
import TrendChart from './components/TrendChart.vue';
const props=defineProps(['tab']);const emit=defineEmits(['navigate']);
const currentStudent=ref('lin');
function switchStudent(){drawer.value=false;dialog.open=false;selected.value=[];detail.value={};revision.value=null;compare.value=false;reason.value='';ocr.value='';verdict.value='待确认';}

const titles={tutoring:['一起把思路讲清楚','从具体题目出发，给孩子适量提示。'],handwriting:['书写观察','按纸张与任务类型观察，不做孩子间排名。'],overview:['看见努力，陪伴每一步成长','把注意力放在学习过程，让陪伴更从容。'],submissions:['作业与核对','先核对识别内容，再确认结论。人工核对不会覆盖机器原始记录。'],mistakes:['错题与复习','按知识点整理薄弱项，用短而适量的练习巩固。'],reports:['学习报告','关注变化和具体努力，不与其他孩子排名。'],schedule:['课表与教材','结合真实教学进度，安排适量的明日预习。'],privacy:['家庭与隐私','清楚知道谁可以访问，以及数据如何被使用。']};
const names=computed(()=>titles[props.tab]||titles.overview);
const submissions=ref([{id:'HW-1025',name:'周长与面积练习',subject:'数学',date:'10/25 16:20',count:'8 题',result:'5 正确 · 2 订正 · 1 待确认',status:'待确认'},{id:'HW-1024',name:'乘除法巩固',subject:'数学',date:'10/24 18:08',count:'10 题',result:'8 正确 · 2 订正',status:'已完成'},{id:'HW-1023',name:'单元词汇练习',subject:'英语',date:'10/23 17:30',count:'12 题',result:'尚未识别',status:'失败'}]);
const mistakes=ref([{id:'ERR-01',name:'长方形周长',subject:'数学',reason:'概念理解',due:'今天',status:'待复习'},{id:'ERR-02',name:'两位数乘一位数',subject:'数学',reason:'计算步骤',due:'明天',status:'订正中'},{id:'ERR-03',name:'除法验算',subject:'数学',reason:'验算习惯',due:'10/28',status:'已掌握'}]);
const selected=ref([]),plans=ref([]),cycle=ref('本周'),drawer=ref(false),detail=ref({}),ocr=ref('长8厘米，宽5厘米，求长方形的周长。'),verdict=ref('待确认'),reason=ref(''),revision=ref(null),compare=ref(false);
const dialog=reactive({open:false,title:'',fields:[],initial:{},note:'',save:()=>{}});
const slots=ref([{id:1,day:'星期一',time:'08:30',subject:'数学',chapter:'长方形和正方形'},{id:2,day:'星期二',time:'09:20',subject:'英语',chapter:'Unit 3'},{id:3,day:'星期三',time:'08:30',subject:'数学',chapter:'周长的应用'}]);
const currentChapter=ref('长方形和正方形');
const guardians=ref([{id:1,name:'林同学的家长',role:'所有者',status:'已验证'},{id:2,name:'监护人 B',role:'共同监护人',status:'已验证'}]),requests=ref([]);
const field=(key,label,options)=>({key,label,required:true,...(options?{type:'select',options}:{})});
function form(title,fields,save,note='',initial={}){Object.assign(dialog,{title,fields,save,note,initial,open:true});}
function saveForm(data){if(dialog.save(data)!==false)dialog.open=false;}
function openWork(action,row){if(action==='重试'){if(row.status!=='失败'){ElMessage.info('仅失败任务可重试');return;}row.status='排队中';ElMessage.success('已模拟排队，未重新上传');return;}detail.value=row;revision.value=row.revision||null;verdict.value=revision.value?.verdict||'待确认';reason.value='';ocr.value=revision.value?.ocr||'长8厘米，宽5厘米，求长方形的周长。';drawer.value=true;}
function revise(){if(!reason.value.trim()){ElMessage.warning('请填写核对依据，保留可追溯记录');return;}revision.value={ocr:ocr.value,verdict:verdict.value,reason:reason.value,version:(revision.value?.version||0)+1};detail.value.revision=revision.value;detail.value.status=verdict.value==='待确认'?'待确认':'已核对';ElMessage.success('已保存核对版本；机器原始结论仍保留');}
function createPlan(){if(!selected.value.length){ElMessage.warning('请先勾选需要复习的题目');return;}form('创建复习计划',[field('name','计划名称'),field('date','复习日期（YYYY-MM-DD）'),field('minutes','每次时长（分钟）',['5','10','15','20'])],data=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||isNaN(Date.parse(data.date))||new Date(data.date).toISOString().slice(0,10)!==data.date){ElMessage.error('请输入有效日期，例如 2026-10-26');return false;}if(selected.value.length>20){ElMessage.error('每次最多 20 题');return false;}plans.value.push({...data,count:selected.value.length});ElMessage.success('已创建本次会话复习计划');},'每次最多 20 题、20 分钟；不依据待确认题目自动生成错题。',{name:'本周周长巩固',date:'2026-10-26',minutes:'10'});}
function editSlot(row){form(row?'编辑课程':'添加课程',[field('day','星期',['星期一','星期二','星期三','星期四','星期五']),field('time','开始时间（HH:mm）'),field('subject','学科',['数学','语文','英语']),field('chapter','教材章节')],data=>{if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(data.time)){ElMessage.error('请输入有效时间');return false;}if(slots.value.some(s=>s.id!==row?.id&&s.day===data.day&&s.time===data.time)){ElMessage.error('该时段已有课程，请调整时间');return false;}if(row)Object.assign(row,data);else slots.value.push({...data,id:Date.now()});ElMessage.success('课表已更新');},'按开始时刻检查重复；生产接口需按课程起止时间校验完整冲突。',row||{});}
function invite(){form('邀请共同监护人',[field('name','监护人称呼'),{...field('email','受邀邮箱'),email:true}],data=>{guardians.value.push({...data,id:Date.now(),role:'共同监护人',status:'待接受'});ElMessage.success('已创建演示邀请记录，未发送邮件');},'受邀者需完成身份验证与授权后才能访问孩子数据；本原型不发送邀请。');}
function privacyRequest(kind){form(`${kind}申请 · 二次验证演示`,[field('code','输入演示验证码 246810'),field('confirm',`输入“确认${kind}”`)],data=>{if(data.code!=='246810'||data.confirm!==`确认${kind}`){ElMessage.error('验证码或确认文字不匹配');return false;}requests.value.unshift({id:'PR-'+Date.now().toString().slice(-6),kind,status:'待处理 · 演示'});ElMessage.success('申请已记录，未导出或删除真实数据');},'仅演示再次验证与申请状态。正式环境验证码必须由服务端验证；删除包括派生数据和供应商删除回执。');}
</script>
<template>
<PageHead :eyebrow="currentStudent==='lin'?'FAMILY / 林同学':'FAMILY / 宁同学'" :title="names[0]" :description="names[1]"><template #actions><label class="student-switch">当前孩子<select v-model="currentStudent" aria-label="切换当前孩子" @change="switchStudent"><option value="lin">林同学 · 三年级</option><option value="ning">宁同学 · 一年级</option></select></label></template></PageHead>
<section v-if="currentStudent==='ning'" class="panel family-empty"><span class="pair-symbol"><Icon name="book" :size="36"/></span><el-tag type="info">宁同学 · 一年级</el-tag><h2>新的学习旅程，从这里开始</h2><p>这个演示孩子还没有作业、复习、课表或报告。没有数据时，不生成正确率和学习结论。</p><el-button type="primary" @click="currentStudent='lin';switchStudent()">返回林同学的学习记录</el-button><p class="muted">切换会关闭旧孩子的详情、核对草稿与批量选择。正式系统按 student_id 重新鉴权和获取数据。</p></section>
<template v-else>
<section v-show="tab==='tutoring'"><ParentTutoring/></section>
<section v-show="tab==='handwriting'"><HandwritingFeedback parent/></section>
<template v-if="tab==='overview'"><div class="parent-summary"><div><span class="eyebrow">THIS WEEK / 本周学习</span><h2>每一点进步，<br>都有认真思考的痕迹。</h2><p>本周完成 6 次练习，主动订正 8 道题。<br>“周长”的理解还需要一点耐心和陪伴。</p><el-button type="primary" @click="emit('navigate','reports')">查看完整学习报告<Icon name="arrow" :size="17"/></el-button></div><div class="weekly-ring"><svg viewBox="0 0 160 160"><circle cx="80" cy="80" r="66"/><circle cx="80" cy="80" r="66" class="ring-progress"/></svg><div class="ring-value"><strong>6<span>/ 8</span></strong><small>本周计划已完成</small></div></div><div class="summary-note"><Icon name="heart"/><strong>陪伴建议</strong><p>可以请孩子画一个长方形，<br>讲一讲“围一圈”是什么意思。</p><span>基于虚构学习记录</span></div></div>
<div class="stat-grid"><article class="stat-card" v-for="s in [{label:'本周练习题',value:'48',unit:'题',icon:'clipboard',note:'只统计已完成的练习'},{label:'已确认正确',value:'36',unit:'题',icon:'tick',note:'待确认 3 题单独列示'},{label:'主动完成订正',value:'8',unit:'题',icon:'pencil',note:'看见订正过程中的努力'},{label:'需要家长核对',value:'3',unit:'题',icon:'alert',note:'字迹不清，不计作错题'}]" :key="s.label"><span class="stat-icon"><Icon :name="s.icon"/></span><span class="stat-label">{{s.label}}</span><div class="stat-value">{{s.value}}<small>{{s.unit}}</small></div><p>{{s.note}}</p></article></div><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><div><h3>学习与订正趋势</h3><p>最近 7 天 · 虚构演示数据</p></div><el-tag type="info">本周</el-tag></div><TrendChart variant="learning"/></section><section class="panel"><div class="panel-heading"><h3>值得关注的事</h3><span class="count-pill">3</span></div><button class="attention-item" @click="emit('navigate','submissions')"><span class="mini-icon amber"><Icon name="clipboard"/></span><div><strong>有作业需要一起核对</strong><p>周长与面积 · 1 份待确认</p></div><Icon name="right"/></button><button class="attention-item" @click="emit('navigate','mistakes')"><span class="mini-icon blue"><Icon name="book"/></span><div><strong>今天适合复习“周长”</strong><p>短时练习，先理解再巩固</p></div><Icon name="right"/></button><button class="attention-item" @click="emit('navigate','schedule')"><span class="mini-icon mint"><Icon name="calendar"/></span><div><strong>确认明日教材进度</strong><p>数学 · 长方形和正方形</p></div><Icon name="right"/></button></section></div><section class="panel"><div class="panel-heading"><h3>最近的作业</h3><el-button link type="primary" @click="emit('navigate','submissions')">查看全部<Icon name="right" :size="16"/></el-button></div><DataGrid :rows="submissions" :columns="[{key:'name',label:'作业名称',width:240},{key:'date',label:'提交时间'},{key:'result',label:'检查摘要',width:230},{key:'status',label:'状态'}]" :actions="['查看详情']" @action="openWork"/></section></template>
<template v-else-if="tab==='submissions'"><div class="inline-note"><Icon name="shield"/>机器原始结论、人工核对版本分别留存；家长改判不会直接进入模型金标准。</div><section class="panel section-gap"><DataGrid :rows="submissions" :columns="[{key:'name',label:'作业名称',width:230},{key:'subject',label:'学科',width:90},{key:'date',label:'提交时间'},{key:'count',label:'题目数',width:90},{key:'result',label:'检查摘要',width:240},{key:'status',label:'状态'}]" :status-options="['待确认','已完成','失败','排队中','已核对']" :actions="['核对详情','重试']" @action="openWork"/></section></template>
<template v-else-if="tab==='mistakes'"><div class="panel"><div class="panel-heading"><div><h3>错题知识库</h3><p>先核对、再归档，避免把识别错误当作能力不足。</p></div><el-button type="primary" @click="createPlan"><Icon name="plus" :size="16"/>创建复习计划</el-button></div><DataGrid :rows="mistakes" :columns="[{key:'name',label:'知识点',width:230},{key:'reason',label:'原因标签'},{key:'due',label:'建议复习时间'},{key:'status',label:'掌握状态'}]" :actions="['查看题目']" selectable :status-options="['待复习','订正中','已掌握']" @selection="selected=$event" @action="(_,r)=>{detail={...r,result:'原作答：13 厘米'};drawer=true;revision=null;}"/></div><div class="panel section-gap"><h3>已安排的复习</h3><el-empty v-if="!plans.length" description="还没有计划，勾选上面的题目开始安排" :image-size="64"/><div v-for="(p,i) in plans" :key="i" class="plan-row"><Icon name="calendar"/><div><strong>{{p.name}}</strong><p>{{p.date}} · {{p.count}} 题 · {{p.minutes}} 分钟</p></div><el-tag>待开始</el-tag><el-button link type="danger" @click="plans.splice(i,1)">取消计划</el-button></div></div></template>
<template v-else-if="tab==='reports'"><div class="panel-heading"><el-radio-group v-model="cycle"><el-radio-button value="本周">本周</el-radio-button><el-radio-button value="上周"/><el-radio-button value="最近30天"/><el-radio-button value="无数据示例"/></el-radio-group><span class="muted">报告数据截至 2026/10/25 · 演示</span></div><el-empty v-if="cycle==='无数据示例'" description="这个周期还没有学习记录，完成第一次练习后再来看看"/><template v-else><div class="report-intro"><Icon name="chart" :size="30"/><div><h2>{{cycle}}学习观察</h2><p>{{cycle==='上周'?'完成 4 次练习，订正 5 题。':'练习逐渐形成习惯，订正时愿意多想一步。'}}样本较少，仅供家庭观察，不作为能力定论。</p></div></div><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><h3>{{cycle}}练习与订正</h3><span class="muted">示例趋势</span></div><TrendChart :key="cycle" variant="learning"/><p class="muted">图表为固定布局示例，尚未接入周期聚合接口。</p></section><section class="panel"><h3>知识点观察</h3><div v-for="k in [{name:'乘除法计算',percent:88},{name:'周长的理解',percent:62},{name:'验算习惯',percent:75}]" :key="k.name" class="knowledge-row"><div><strong>{{k.name}}</strong><span>{{k.percent}}% · 示例</span></div><el-progress :percentage="k.percent" :show-text="false"/></div><p class="muted">分母仅包含已确认题目；待确认另列。</p></section></div><div class="gentle-note"><Icon name="heart"/><div><strong>给家长的一点建议</strong><p>用家里的相框或书本边框讲“周长”，请孩子自己说出思路。认可认真尝试，不用分数给孩子贴标签。</p></div></div></template></template>
<template v-else-if="tab==='schedule'"><div class="panel"><div class="panel-heading"><div><h3>一周课表</h3><p>2026—2027 学年 · 上学期</p></div><el-button type="primary" @click="editSlot()"><Icon name="plus" :size="16"/>添加课程</el-button></div><div class="schedule-grid"><div v-for="day in ['星期一','星期二','星期三','星期四','星期五']" :key="day" class="schedule-day"><h4>{{day}}</h4><button v-for="s in slots.filter(s=>s.day===day)" :key="s.id" class="lesson-card" @click="editSlot(s)"><span>{{s.time}}</span><h3>{{s.subject}}</h3><p>{{s.chapter}}</p><small>点击编辑</small></button><span v-if="!slots.some(s=>s.day===day)" class="schedule-empty">尚未安排</span></div></div></div><div class="panel section-gap"><div class="panel-heading"><div><h3>教材与当前进度</h3><p>仅选择已授权、已审核发布的版本</p></div><el-tag type="success">版本已锁定</el-tag></div><div class="book-item"><span class="book-cover">数学<small>三年级 / 上册</small><Icon name="book" :size="32"/></span><div><h3>数学 · 演示教材 2026 版</h3><p>当前章节：{{currentChapter}}</p><p class="muted">来源：授权教材 DEMO-003 · 第 1 页</p><el-button @click="form('更新教材进度',[field('chapter','当前章节',['长方形和正方形','周长的应用','单元复习'])],data=>{currentChapter=data.chapter;slots.filter(s=>s.subject==='数学').forEach(s=>s.chapter=data.chapter);ElMessage.success('数学课程进度已更新');},'仅更新演示课表；正式版本需绑定已发布教材章节。')">更新教学进度</el-button></div></div></div></template>
<template v-else-if="tab==='privacy'"><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><div><h3>家庭成员与监护授权</h3><p>林同学的家庭 · 仅演示身份</p></div><el-button type="primary" @click="invite">邀请监护人</el-button></div><div v-for="g in guardians" :key="g.id" class="member-row"><span class="avatar">{{g.name.slice(0,1)}}</span><div><strong>{{g.name}}</strong><p>{{g.role}} · {{g.status}}</p></div><el-button v-if="g.role!=='所有者'&&g.status!=='已撤回'" link type="danger" @click="form('撤回监护人访问',[field('confirm','输入“确认撤回”')],data=>{if(data.confirm!=='确认撤回'){ElMessage.error('请输入确认撤回');return false;}g.status='已撤回';},'演示撤回仅修改本页状态；真实环境需立即失效全部会话与内容链接。')">撤回</el-button></div></section><section class="panel"><h3>本月使用额度</h3><div class="quota-value">286 <span>/ 500 页</span></div><el-progress :percentage="57" :show-text="false"/><p class="muted">演示套餐 · 家长管理消费，孩子端没有付费入口</p><div class="mapping-row"><span>本月已使用</span><strong>¥28.60 · 示例</strong></div><div class="mapping-row"><span>自动续费</span><strong>未开通</strong></div></section></div><div class="panel section-gap"><h3>数据由家庭掌控</h3><div class="privacy-option"><span class="mini-icon blue"><Icon name="download"/></span><div><h4>导出家庭学习数据</h4><p>再次验证身份后生成带有效期的下载任务。</p></div><el-button @click="privacyRequest('导出')">申请导出</el-button></div><div class="privacy-option"><span class="mini-icon amber"><Icon name="trash"/></span><div><h4>删除学习数据</h4><p>确认范围、验证身份，并追踪原始及派生数据删除状态。</p></div><el-button type="danger" plain @click="privacyRequest('删除')">申请删除</el-button></div><div v-for="r in requests" :key="r.id" class="mapping-row"><span>{{r.id}} · {{r.kind}}</span><el-tag type="warning">{{r.status}}</el-tag></div></div></template>
<el-drawer v-model="drawer" title="作业核对与版本记录" size="680px"><div class="drawer-heading"><div><span class="eyebrow">{{detail.id}}</span><h2>{{detail.name}}</h2></div><el-tag>{{detail.status}}</el-tag></div><el-alert title="以下是固定作业样例，用于演示核对流程；未读取任何儿童真实内容。" type="info" :closable="false"/><div class="paper-preview"><span>数学 · 第 2 题 / 原图示意</span><h3>长方形长 8 厘米，宽 5 厘米。<br>求它的周长。</h3><div class="handwriting">8 + 5 = 13（厘米）</div></div><div class="machine-record"><Icon name="lock"/><div><strong>机器原始记录 · v1 · 只读</strong><p>结论：需订正 · 识别置信度不足，进入待确认</p></div></div><el-form label-position="top" class="section-gap"><el-form-item label="核对识别文本"><el-input v-model="ocr" type="textarea" :rows="3" maxlength="500"/></el-form-item><el-form-item label="家长核对结论"><el-radio-group v-model="verdict"><el-radio value="正确">正确</el-radio><el-radio value="需订正">需订正</el-radio><el-radio value="待确认">待确认</el-radio></el-radio-group></el-form-item><el-form-item label="核对依据（必填）"><el-input v-model="reason" placeholder="例如：对照原图确认漏写了两条边" maxlength="300"/></el-form-item></el-form><div class="button-row"><el-button type="primary" @click="revise">保存核对版本</el-button><el-button @click="compare=!compare">{{compare?'收起版本说明':'查看版本说明'}}</el-button></div><div v-if="compare" class="hint-box">每次保存新增人工修订版本，保留机器结果与操作者依据。核对数据只能进入候选池，经双人标注后才可能成为金标准。</div><div v-if="revision" class="result-banner"><Icon name="tick"/><div><strong>人工核对 v{{revision.version}}：{{revision.verdict}}</strong><p>{{revision.reason}}</p></div></div></el-drawer>
<FormDialog v-model="dialog.open" :title="dialog.title" :fields="dialog.fields" :initial="dialog.initial" :note="dialog.note" @save="saveForm"/>
</template>
</template>
